import java.util.*;

class Solution {
    public List<Integer> minSubsequence(int[] nums) {
        Arrays.sort(nums);
        int total = 0;
        for (int v : nums) total += v;
        List<Integer> res = new ArrayList<>();
        int takenSum = 0;
        for (int i = nums.length - 1; i >= 0; i--) {
            res.add(nums[i]);
            takenSum += nums[i];
            if (takenSum > total - takenSum) break;
        }
        return res;
    }
}

